CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, phone VARCHAR(20), password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL);
CREATE TABLE auth_sessions (token_hash VARCHAR(64) PRIMARY KEY, user_id BIGINT NOT NULL, expires_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), INDEX idx_session_expiry(expires_at));
CREATE TABLE addresses (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, name VARCHAR(100), phone VARCHAR(20), line1 VARCHAR(255), line2 VARCHAR(255), city VARCHAR(100), state VARCHAR(100), pin VARCHAR(6), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE categories (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, slug VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE products (id BIGINT AUTO_INCREMENT PRIMARY KEY, category_id BIGINT, name VARCHAR(200) NOT NULL, collection VARCHAR(100), occasion VARCHAR(60), colour VARCHAR(60), description VARCHAR(4000), specifications TEXT, price DECIMAL(12,2) NOT NULL, original_price DECIMAL(12,2), stock INT NOT NULL DEFAULT 0, archived BOOLEAN NOT NULL DEFAULT FALSE, demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP(6) NOT NULL, version BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(category_id) REFERENCES categories(id), CONSTRAINT positive_price CHECK(price>0), CONSTRAINT positive_stock CHECK(stock>=0), CONSTRAINT original_price_valid CHECK(original_price IS NULL OR original_price>=price), INDEX idx_product_filter(archived,collection,colour,occasion), INDEX idx_product_price(price), INDEX idx_product_created(created_at));
CREATE TABLE product_images (id BIGINT AUTO_INCREMENT PRIMARY KEY, product_id BIGINT NOT NULL, url VARCHAR(1000) NOT NULL, label VARCHAR(100), position INT NOT NULL DEFAULT 0, FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE reviews (id BIGINT AUTO_INCREMENT PRIMARY KEY, product_id BIGINT NOT NULL, user_id BIGINT NOT NULL, rating INT NOT NULL, text VARCHAR(2000), display_name VARCHAR(100), created_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(user_id) REFERENCES users(id), UNIQUE(product_id,user_id), CHECK(rating BETWEEN 1 AND 5));
CREATE TABLE carts (owner_key VARCHAR(80) PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE cart_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, owner_key VARCHAR(80) NOT NULL, product_id BIGINT NOT NULL, quantity INT NOT NULL, FOREIGN KEY(owner_key) REFERENCES carts(owner_key), FOREIGN KEY(product_id) REFERENCES products(id), UNIQUE(owner_key,product_id), CHECK(quantity BETWEEN 1 AND 10));
CREATE TABLE wishlists (id BIGINT AUTO_INCREMENT PRIMARY KEY, owner_key VARCHAR(80) NOT NULL, product_id BIGINT NOT NULL, FOREIGN KEY(owner_key) REFERENCES carts(owner_key), FOREIGN KEY(product_id) REFERENCES products(id), UNIQUE(owner_key,product_id));
CREATE TABLE orders (id VARCHAR(40) PRIMARY KEY, owner_key VARCHAR(80) NOT NULL, idempotency_key VARCHAR(80) NOT NULL, request_hash VARCHAR(64) NOT NULL, user_id BIGINT, status VARCHAR(40) NOT NULL, fulfillment VARCHAR(30) NOT NULL, gateway_order_id VARCHAR(100) UNIQUE, payment_id VARCHAR(100) UNIQUE, delivery TEXT NOT NULL, subtotal DECIMAL(12,2) NOT NULL, discount DECIMAL(12,2) NOT NULL, shipping DECIMAL(12,2) NOT NULL, tax DECIMAL(12,2) NOT NULL, total DECIMAL(12,2) NOT NULL, created_at TIMESTAMP(6) NOT NULL, expires_at TIMESTAMP(6) NOT NULL, reservation_released BOOLEAN NOT NULL DEFAULT FALSE, cart_cleared BOOLEAN NOT NULL DEFAULT FALSE, version BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(user_id) REFERENCES users(id), UNIQUE(owner_key,idempotency_key), INDEX idx_orders_expiry(status,expires_at));
CREATE TABLE order_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id VARCHAR(40) NOT NULL, product_id BIGINT, name VARCHAR(200) NOT NULL, collection VARCHAR(100), image VARCHAR(1000), unit_price DECIMAL(12,2) NOT NULL, original_price DECIMAL(12,2), quantity INT NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE payments (id VARCHAR(100) PRIMARY KEY, order_id VARCHAR(40) NOT NULL, status VARCHAR(40) NOT NULL, amount BIGINT NOT NULL, currency VARCHAR(3) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE webhook_events (id VARCHAR(100) PRIMARY KEY, processed_at TIMESTAMP(6) NOT NULL);
